-- KeySuite V2.02 ES Price List import (260731 V1.0)
begin;
create table if not exists public.ks_es_pricelist (
  company_id text not null,
  model text not null,
  variant text not null,
  currency text not null default 'USD',
  base_price numeric(14,2) not null,
  multiplier numeric(14,4) not null default 5.8,
  source_version text not null,
  updated_at timestamptz not null default now(),
  primary key(company_id,model,variant,currency)
);
alter table public.ks_es_pricelist enable row level security;
drop policy if exists ks_es_pricelist_company_read on public.ks_es_pricelist;
create policy ks_es_pricelist_company_read on public.ks_es_pricelist for select to authenticated
using (company_id=public.keysuite_current_company_id());
drop policy if exists ks_es_pricelist_company_write on public.ks_es_pricelist;
create policy ks_es_pricelist_company_write on public.ks_es_pricelist for all to authenticated
using (company_id=public.keysuite_current_company_id() and public.keysuite_permission_level('manage_price_list')='full')
with check (company_id=public.keysuite_current_company_id() and public.keysuite_permission_level('manage_price_list')='full');
delete from public.ks_es_pricelist where company_id=public.keysuite_current_company_id() and source_version='260731-V1.0';
on conflict(company_id,model,variant,currency) do update set base_price=excluded.base_price,multiplier=excluded.multiplier,source_version=excluded.source_version,updated_at=now();
on conflict(company_id,model,variant,currency) do update set base_price=excluded.base_price,multiplier=excluded.multiplier,source_version=excluded.source_version,updated_at=now();
on conflict(company_id,model,variant,currency) do update set base_price=excluded.base_price,multiplier=excluded.multiplier,source_version=excluded.source_version,updated_at=now();
on conflict(company_id,model,variant,currency) do update set base_price=excluded.base_price,multiplier=excluded.multiplier,source_version=excluded.source_version,updated_at=now();
on conflict(company_id,model,variant,currency) do update set base_price=excluded.base_price,multiplier=excluded.multiplier,source_version=excluded.source_version,updated_at=now();
notify pgrst,'reload schema';
commit;